201	/**
202	 * 部署行为由这几个文件决定 —— 也就是「正在跑的这套流程」自己的身份。
203	 * 它们必须与被部署的那个 sha 对齐，否则「改了部署流程」这件事本身永远不生效。
204	 */
205	const MACHINERY = [
206	  "scripts/deploy.ts",
207	  "lib/deploy-supervisor.ts",
208	  "lib/deploy-state.ts",
209	];
210	
211	/** 某个 commit 里这个路径的 blob sha；null = 那个版本里没有这个文件。 */
212	async function blobInCommit(sha: string, p: string): Promise<string | null> {
213	  const r = await run(["git", "rev-parse", `${sha}:${p}`], { quiet: true });
214	  return r.code === 0 ? r.stdout.trim() : null;
215	}
216	
217	/** 磁盘上这个文件的 blob sha（= 本次真正在执行的那份代码）。 */
218	async function blobOnDisk(p: string): Promise<string | null> {
219	  if (!fs.existsSync(path.join(REPO, p))) return null;
220	  const r = await run(["git", "hash-object", p], { quiet: true });
221	  return r.code === 0 ? r.stdout.trim() : null;
222	}
223	
224	/**
225	 * 「干活的这套部署流程」是不是被部署那个版本里的那一套。
226	 *
227	 * 这是 S86 连栽两次的坑：脚本从**工作树**跑，而界面「更新到最新」部署的是
228	 * `origin/main`（`app/api/update/route.ts:55` 的默认值）。于是 fetch 到了新
229	 * commit、release 里装的是新代码，干活的却还是工作树里那份旧脚本 —— 修的正是
230	 * 部署流程本身时，改动静默失效，报错一模一样地再来一遍。
231	 *
232	 * 区分两种不一致，只拦真正会骗人的那种：
233	 *   落后（HEAD 是目标的祖先）→ 拦。新版流程压根没参与，本次部署名不副实。
234	 *   本地未提交改动 → 只提醒。开发时的常态，且磁盘上这份就是你想跑的那份。
235	 */
236	async function checkMachinery(sha: string, force: boolean): Promise<void> {
237	  const stale: string[] = [];
238	  const edited: string[] = [];
